/* @lc app=leetcode id=2954 lang=kotlin */ class Solution { fun numberOfSequence(n: Int, sick: IntArray): Int = 1000000007L.let { MOD -> { b: Long, e: Long -> (0..30).fold(1L to b) { (r, c), i -> (if ((e shr i) and 1L != 0L) r * c % MOD else r) to (c * c % MOD) }.first }.let { pow -> (1..n).scan(1L) { acc, i -> acc * i % MOD }.toLongArray().let { fac -> (fac[n - sick.size] * pow(fac[sick[0]], MOD - 2) % MOD * pow(fac[n - 1 - sick.last()], MOD - 2) % MOD * (1 until sick.size).fold(1L) { acc, i -> (sick[i] - sick[i - 1] - 1).let { g -> if (g > 0) acc * pow(2L, g - 1L) % MOD * pow(fac[g], MOD - 2) % MOD else acc } } % MOD).toInt() } } } }